/**
 * The type an open name's value is read under: `xs:anySimpleType`, its whitespace preserved, since
 * no declaration governs it (fin.md, D2).
 */
export const openAttribute: GlobalAttributeDeclaration = global(
  "xs:anySimpleType",
  xsAnySimpleTypeType,
  xsAnySimpleTypeDomain,
);

/**
 * A governing type's declarations.
 *
 * @param owner - The type's `TypeName` handle.
 * @param attributes - Its attributes.
 * @returns The rows.
 */
const typeDeclares = (
  owner: string,
  attributes: readonly DeclaredAttribute[],
): readonly TypeAttributeDeclaration[] => attributes.map((declared) => ({ ...declared, owner }));

/**
 * A governing type's attribute wildcard.
 *
 * @param owner - The type's `TypeName` handle.
 * @param namespace - Its namespace constraint.
 * @param processing - Its processing.
 * @returns The row.
 */
const typeWildcard = (
  owner: string,
  namespace: NamespaceConstraint,
  processing: Processing,
): TypeAttributeWildcard => ({ namespace, owner, processing });

/**
 * A named type's text type.
 *
 * @param owner - The type's `TypeName` handle.
 * @param type - Its simple type.
 * @param domain - Its simple type's domain.
 * @returns The row.
 */
const typeText = (owner: string, type: ValueType, domain: Domain): TypeText => ({
  domain,
  owner,
  type,
});

